package com.farika.soundflow;
import android.app.Application;import android.content.Context;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WaveCatalog170Test {
 Context c;@Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();}
 Library.Track song(String id)throws Exception{return LibraryUi163Test.song(id,"Track "+id);}
 @Test public void generatedTrackIsLookedUpWithoutLoadingWholeLibrary()throws Exception{new WaveCatalog(c).put(Collections.singletonList(song("1")));assertTrue(new Library(c).tracks.isEmpty());assertEquals("Track 1",new Library(c).find("sc:1").title);}
 @Test public void cacheDoesNotDeleteOrRewriteLibraryEntries()throws Exception{Library l=new Library(c);l.upsert(song("1"));l.save();String before=c.getSharedPreferences("library",0).getString("tracks","");new WaveCatalog(c).put(Arrays.asList(song("2"),song("3")));assertEquals(before,c.getSharedPreferences("library",0).getString("tracks",""));assertNotNull(new Library(c).find("sc:1"));}
 @Test public void catalogIsScopedToAccount()throws Exception{new WaveCatalog(c).put(Collections.singletonList(song("1")));c.getSharedPreferences("profile",0).edit().putString("id","456").commit();assertNull(new WaveCatalog(c).get("sc:1"));c.getSharedPreferences("profile",0).edit().putString("id","123").commit();assertNotNull(new WaveCatalog(c).get("sc:1"));}
 @Test public void likedStateOnlyChangesWhenCalledAfterConfirmation()throws Exception{new WaveCatalog(c).put(Collections.singletonList(song("1")));new WaveCatalog(c).liked("1",false);assertFalse(new Library(c).find("sc:1").liked);new WaveCatalog(c).liked("1",true);assertTrue(new Library(c).find("sc:1").liked);}
 @Test public void remoteFieldsAreSanitized()throws Exception{Library.Track t=song("1");t.remote.put("stream_url","https://synthetic.invalid/secret");new WaveCatalog(c).put(Collections.singletonList(t));assertFalse(new WaveCatalog(c).get(t.uri).remote.has("stream_url"));}
 @Test public void recentReadHasBoundedRowCountWithoutDeletingRecords()throws Exception{ArrayList<Library.Track> tracks=new ArrayList<>();for(int i=0;i<350;i++)tracks.add(song(""+i));new WaveCatalog(c).put(tracks);assertEquals(300,new WaveCatalog(c).recent().size());assertNotNull(new WaveCatalog(c).get("sc:0"));assertTrue(new Library(c).tracks.isEmpty());}
 @Test public void checkpointCanRestoreGeneratedTrackAndWaveFlag()throws Exception{new WaveCatalog(c).put(Arrays.asList(song("1"),song("2")));PlaybackCheckpoint.save(c,Arrays.asList("sc:1","sc:2"),1,45000,false,false,true,false,false,false,true);PlaybackCheckpoint.Snapshot s=PlaybackCheckpoint.read(c);assertEquals("sc:2",s.current());assertEquals(45000,s.position);assertTrue(s.wave);}
}
